# прочитайте n и проверьте n случаев

solution:
def square(x):
    return x * x


n = int(input())
passed = 0
for _ in range(n):
    x, expected = (int(v) for v in input().split())
    got = square(x)
    if got == expected:
        print("ок", x)
        passed += 1
    else:
        print(f"ошибка {x}: получено {got}, ожидалось {expected}")
print(f"пройдено {passed} из {n}")
